const { parseReviewRequest } = require('../../lib/reviewRequest');

describe('parseReviewRequest', () => {
  it('parses approve and reject', () => {
    expect(parseReviewRequest({ decision: 'approve' })).toEqual({ ok: true, decision: 'approve', note: null });
    expect(parseReviewRequest({ decision: 'reject', note: 'blurry' })).toEqual({ ok: true, decision: 'reject', note: 'blurry' });
  });

  it('trims notes and turns empty ones into null', () => {
    expect(parseReviewRequest({ decision: 'approve', note: '  nice  ' }).note).toBe('nice');
    expect(parseReviewRequest({ decision: 'approve', note: '   ' }).note).toBeNull();
    expect(parseReviewRequest({ decision: 'approve', note: '' }).note).toBeNull();
    expect(parseReviewRequest({ decision: 'approve', note: null }).note).toBeNull();
    expect(parseReviewRequest({ decision: 'approve', note: undefined }).note).toBeNull();
  });

  it('accepts a note of exactly 500 characters and rejects 501', () => {
    expect(parseReviewRequest({ decision: 'reject', note: 'x'.repeat(500) }).ok).toBe(true);
    expect(parseReviewRequest({ decision: 'reject', note: 'x'.repeat(501) })).toEqual({ ok: false, message: 'note must be at most 500 characters' });
  });

  it('measures the note length after trimming', () => {
    expect(parseReviewRequest({ decision: 'reject', note: ` ${'x'.repeat(500)} ` }).ok).toBe(true);
  });

  it.each([[null], [undefined], [[]], ['approve'], [5], [true]])('rejects a non-object body: %p', (body) => {
    expect(parseReviewRequest(body)).toEqual({ ok: false, message: 'Request body must be a JSON object' });
  });

  it.each([[{}], [{ decision: 'Approve' }], [{ decision: 'maybe' }], [{ decision: 1 }], [{ decision: null }], [{ decision: ['approve'] }]])(
    'rejects an invalid decision: %p',
    (body) => {
      expect(parseReviewRequest(body)).toEqual({ ok: false, message: 'decision must be "approve" or "reject"' });
    }
  );

  it('rejects a non-string note', () => {
    expect(parseReviewRequest({ decision: 'approve', note: 5 })).toEqual({ ok: false, message: 'note must be a string' });
    expect(parseReviewRequest({ decision: 'approve', note: {} })).toEqual({ ok: false, message: 'note must be a string' });
  });

  it('returns exactly ok, decision and note on success', () => {
    expect(Object.keys(parseReviewRequest({ decision: 'approve', extra: 1 })).sort()).toEqual(['decision', 'note', 'ok']);
  });
});

