const { resolveImageProviderConfig } = require('../../lib/imageProvider');

const DISABLED = (reason) => ({ name: 'disabled', enabled: false, isFixture: false, reason });

describe('resolveImageProviderConfig', () => {
  it('defaults to disabled', () => {
    expect(resolveImageProviderConfig()).toEqual(DISABLED('Image generation is disabled.'));
    expect(resolveImageProviderConfig({})).toEqual(DISABLED('Image generation is disabled.'));
    expect(resolveImageProviderConfig({ WORKSPACE_IMAGE_PROVIDER: '' })).toEqual(DISABLED('Image generation is disabled.'));
    expect(resolveImageProviderConfig({ WORKSPACE_IMAGE_PROVIDER: 'disabled' })).toEqual(DISABLED('Image generation is disabled.'));
  });

  it('enables the dev fixture only outside production with the explicit flag', () => {
    expect(resolveImageProviderConfig({ WORKSPACE_IMAGE_PROVIDER: 'dev-fixture', WORKSPACE_ENABLE_DEV_FIXTURE: '1' })).toEqual({
      name: 'dev-fixture', enabled: true, isFixture: true, reason: null
    });
    expect(resolveImageProviderConfig({ WORKSPACE_IMAGE_PROVIDER: 'dev-fixture', WORKSPACE_ENABLE_DEV_FIXTURE: '1', NODE_ENV: 'development' }).enabled).toBe(true);
    expect(resolveImageProviderConfig({ WORKSPACE_IMAGE_PROVIDER: 'dev-fixture', WORKSPACE_ENABLE_DEV_FIXTURE: '1', NODE_ENV: 'test' }).enabled).toBe(true);
  });

  it('requires WORKSPACE_ENABLE_DEV_FIXTURE to be exactly "1"', () => {
    const reason = 'The development fixture provider requires WORKSPACE_ENABLE_DEV_FIXTURE=1.';
    expect(resolveImageProviderConfig({ WORKSPACE_IMAGE_PROVIDER: 'dev-fixture' })).toEqual(DISABLED(reason));
    expect(resolveImageProviderConfig({ WORKSPACE_IMAGE_PROVIDER: 'dev-fixture', WORKSPACE_ENABLE_DEV_FIXTURE: 'true' })).toEqual(DISABLED(reason));
    expect(resolveImageProviderConfig({ WORKSPACE_IMAGE_PROVIDER: 'dev-fixture', WORKSPACE_ENABLE_DEV_FIXTURE: '0' })).toEqual(DISABLED(reason));
  });

  it('never enables the fixture in production, even with the flag', () => {
    expect(resolveImageProviderConfig({ WORKSPACE_IMAGE_PROVIDER: 'dev-fixture', WORKSPACE_ENABLE_DEV_FIXTURE: '1', NODE_ENV: 'production' })).toEqual(
      DISABLED('The development fixture provider is not available in production.')
    );
    expect(resolveImageProviderConfig({ WORKSPACE_IMAGE_PROVIDER: 'dev-fixture', NODE_ENV: 'production' })).toEqual(
      DISABLED('The development fixture provider is not available in production.')
    );
  });

  it('keeps unknown or real providers disabled', () => {
    expect(resolveImageProviderConfig({ WORKSPACE_IMAGE_PROVIDER: 'fashn' })).toEqual(DISABLED('Image provider "fashn" is not supported yet.'));
    expect(resolveImageProviderConfig({ WORKSPACE_IMAGE_PROVIDER: 'comfy-cloud', WORKSPACE_ENABLE_DEV_FIXTURE: '1' })).toEqual(
      DISABLED('Image provider "comfy-cloud" is not supported yet.')
    );
  });

  it('returns exactly name, enabled, isFixture and reason', () => {
    expect(Object.keys(resolveImageProviderConfig({})).sort()).toEqual(['enabled', 'isFixture', 'name', 'reason']);
  });
});

