const { shouldFailOrphanedImageJob, DEFAULT_ORPHAN_GRACE_MS } = require('../../lib/orphanedJob');

const UPDATED = '2026-01-01T00:00:00.000Z';
const at = (ms) => new Date(Date.parse(UPDATED) + ms);
const job = (extra = {}) => ({ imageStatus: 'processing', externalRef: null, updatedAt: UPDATED, ...extra });

describe('shouldFailOrphanedImageJob', () => {
  it('exposes a 60 second default grace period', () => {
    expect(DEFAULT_ORPHAN_GRACE_MS).toBe(60000);
  });

  it('fails an old in-flight job nobody is running', () => {
    expect(shouldFailOrphanedImageJob(job(), { now: at(120000) })).toBe(true);
    expect(shouldFailOrphanedImageJob(job({ imageStatus: 'requested' }), { now: at(120000) })).toBe(true);
  });

  it('respects the grace period; the boundary is inclusive', () => {
    expect(shouldFailOrphanedImageJob(job(), { now: at(59999) })).toBe(false);
    expect(shouldFailOrphanedImageJob(job(), { now: at(60000) })).toBe(true);
    expect(shouldFailOrphanedImageJob(job(), { now: at(500), graceMs: 1000 })).toBe(false);
    expect(shouldFailOrphanedImageJob(job(), { now: at(1000), graceMs: 1000 })).toBe(true);
  });

  it('never fails a job this process is running', () => {
    expect(shouldFailOrphanedImageJob(job(), { isRunningHere: true, now: at(600000) })).toBe(false);
  });

  it('never fails a job that has an external provider reference', () => {
    expect(shouldFailOrphanedImageJob(job({ externalRef: 'provider-job-1' }), { now: at(600000) })).toBe(false);
  });

  it.each(['not_requested', 'ready_for_review', 'approved', 'rejected', 'failed', 'bogus', undefined])(
    'never fails a job whose image status is %p',
    (imageStatus) => {
      expect(shouldFailOrphanedImageJob(job({ imageStatus }), { now: at(600000) })).toBe(false);
    }
  );

  it('returns false for missing jobs and unparseable timestamps', () => {
    expect(shouldFailOrphanedImageJob(null, { now: at(600000) })).toBe(false);
    expect(shouldFailOrphanedImageJob(undefined)).toBe(false);
    expect(shouldFailOrphanedImageJob(job({ updatedAt: 'garbage' }), { now: at(600000) })).toBe(false);
    expect(shouldFailOrphanedImageJob(job({ updatedAt: null }), { now: at(600000) })).toBe(false);
    expect(shouldFailOrphanedImageJob(job({ updatedAt: undefined }), { now: at(600000) })).toBe(false);
  });

  it('works with no options (defaults: not running here, now = current time)', () => {
    expect(shouldFailOrphanedImageJob(job({ updatedAt: '2000-01-01T00:00:00.000Z' }))).toBe(true);
    expect(shouldFailOrphanedImageJob(job({ updatedAt: new Date().toISOString() }))).toBe(false);
  });
});
